func readNoFollow(path string, maximum int64) ([]byte, os.FileInfo, error) {
	fd, e := unix.Open(path, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if e != nil {
		return nil, nil, e
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	before, e := f.Stat()
	if e != nil {
		return nil, nil, e
	}
	if !before.Mode().IsRegular() || before.Size() > maximum {
		return nil, nil, fmt.Errorf("%s must be a regular file no larger than %d bytes", path, maximum)
	}
	wire, e := io.ReadAll(io.LimitReader(f, maximum+1))
	if e != nil {
		return nil, nil, e
	}
	after, e := f.Stat()
	if e != nil {
		return nil, nil, e
	}
	named, e := os.Lstat(path)
	if e != nil {
		return nil, nil, e
	}
	if int64(len(wire)) > maximum || !os.SameFile(before, after) || !os.SameFile(before, named) || before.Size() != after.Size() || before.ModTime() != after.ModTime() {
		return nil, nil, fmt.Errorf("%s changed during readback", path)
	}
	return wire, before, nil
}
func LoadJSON(path string, maximum int64) (Object, []byte, error) {
	wire, _, e := readNoFollow(path, maximum)
	if e != nil {
		return nil, nil, e
	}
	var o Object
	e = json.Unmarshal(wire, &o)
	if e != nil {
		return nil, nil, fmt.Errorf("%s invalid JSON: %w", path, e)
	}
	if o == nil {
		return nil, nil, fmt.Errorf("%s must be a JSON object", path)
	}
	return o, wire, nil
}
func load(path string, maximum int64) (Object, []byte) {
	o, b, e := LoadJSON(path, maximum)
	if e != nil {
		fail("%v", e)
	}
	return o, b
}
func VerifyPinnedFile(path, hash, label string, executable bool) (err error) {
	defer recoverError(&err)
	verifyPin(path, hash, label, executable)
	return
}
func verifyPin(path, hash, label string, executable bool) {
	if !filepath.IsAbs(path) || !hashRE.MatchString(hash) {
		fail("%s requires an absolute path and exact SHA-256", label)
	}
	maximum := int64(16 << 20)
	if executable {
		maximum = MaxProbeBytes
	}
	b, m, e := readNoFollow(path, maximum)
	if e != nil {
		fail("%s pinned source file is unavailable: %v", label, e)
	}
	if Hash(b) != hash {
		fail("%s pinned source file SHA-256 differs", label)
	}
	if executable && (m.Mode().Perm()&0111 == 0 || m.Mode().Perm()&0022 != 0) {
		fail("%s must be an executable without group/world write", label)
	}
}
func privateFile(path, label string) {
	b, m, e := readNoFollow(path, 16<<20)
	if e != nil || len(b) == 0 {
		fail("%s private file unavailable: %v", label, e)
	}
	st := m.Sys().(*syscall.Stat_t)
	if m.Mode().Perm()&0077 != 0 || m.Mode().Perm()&0400 == 0 || st.Nlink != 1 || st.Uid != uint32(os.Getuid()) {
		fail("%s must be a current-user-owned private regular file with one link", label)
	}
}
func pinReason(o Object, p, h, label string, executable bool, reasons *[]string) {
	if e := VerifyPinnedFile(str(o, p), str(o, h), label, executable); e != nil {
		*reasons = append(*reasons, e.Error())
	}
}
func writeJSON(path string, v any, exclusive bool) error {
	flags := os.O_WRONLY | os.O_CREATE | os.O_TRUNC
	if exclusive {
		flags = os.O_WRONLY | os.O_CREATE | os.O_EXCL
	}
	fd, e := unix.Open(path, flags|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0600)
	if e != nil {
		return e
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	b, e := json.Marshal(v, json.Deterministic(true))
	if e != nil {
		return e
	}
	if _, e = f.Write(append(b, '\n')); e != nil {
		return e
	}
	return f.Sync()
}

func Root(t testing.TB) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("cannot locate repository test support")
	}
	return filepath.Clean(filepath.Join(filepath.Dir(file), "../../.."))
}

func Write(t testing.TB, path string, data []byte, mode os.FileMode) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, data, mode); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, mode); err != nil {
		t.Fatal(err)
	}
}

func Read(t testing.TB, path string) []byte {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return data
}

// Run runs a command after recording the whole repository tree as its
// input, so any edit anywhere re-runs the test. Prefer Track with the
// command's real inputs, then Exec.
func Run(t *testing.T, dir string, env map[string]string, name string, args ...string) Result {
	t.Helper()
	Track(t, ".")
	return Exec(t, dir, env, name, args...)
}

// Exec is Run without recording the repository tree. Use it only when the
// command's every repository input is already part of the test's cache key:
// embedded with go:embed, opened by the test process itself (including
// copies it makes into a temporary directory), or named with Track. The test
// then re-runs only when its own package or those inputs change.
func Exec(t *testing.T, dir string, env map[string]string, name string, args ...string) Result {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 3*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error { return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL) }
	cmd.WaitDelay = 2 * time.Second
	cmd.Dir = dir
	cmd.Env = os.Environ()
	for key, value := range env {
		prefix := key + "="
		for i := len(cmd.Env) - 1; i >= 0; i-- {
			if strings.HasPrefix(cmd.Env[i], prefix) {
				cmd.Env = append(cmd.Env[:i], cmd.Env[i+1:]...)
			}
		}
		cmd.Env = append(cmd.Env, prefix+value)
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err := cmd.Run()
	if ctx.Err() != nil {
		t.Fatalf("%s exceeded its command deadline: %v", name, ctx.Err())
	}
	code := 0
	if err != nil {
		if exit, ok := errors.AsType[*exec.ExitError](err); ok {
			code = exit.ExitCode()
		} else {
			t.Fatalf("start %s: %v", name, err)
		}
	}
	return Result{stdout.String(), stderr.String(), code}
}

func digest(raw []byte) string { h := sha256.Sum256(raw); return hex.EncodeToString(h[:]) }
func jsonWire(t *testing.T, value any) []byte {
	t.Helper()
	b, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		t.Fatal(err)
	}
	return append(b, '\n')
}
func decodeObject(t *testing.T, raw []byte) object {
	t.Helper()
	var o object
	if err := json.Unmarshal(raw, &o); err != nil {
		t.Fatalf("decode observation: %v\n%s", err, raw)
	}
	return o
}
func field(o object, key string) object { return o[key].(map[string]any) }
func assertEqual(t *testing.T, got, want any) {
	t.Helper()
	if string(jsonWire(t, got)) != string(jsonWire(t, want)) {
		t.Fatalf("got %#v, want %#v", got, want)
	}
}
func assertContains(t *testing.T, got, want string) {
	t.Helper()
	if !strings.Contains(got, want) {
		t.Fatalf("%q does not contain %q", got, want)
	}
}

func exampleManifest(t *testing.T) object {
	t.Helper()
	return decodeObject(t, script.Read(t, filepath.Join(script.Root(t), "tests/runtime_priority/example-dry-run.json")))
}
func cloneObject(t *testing.T, o object) object { t.Helper(); return decodeObject(t, jsonWire(t, o)) }
func errorObservation(err error) object {
	if err == nil {
		return object{}
	}
	return object{"error": err.Error(), "error_type": rp.ErrorType(err)}
}
func normalize(t *testing.T, value any) object {
	t.Helper()
	return decodeObject(t, jsonWire(t, value))
}
func validateManifest(t *testing.T, m object, dry, allocations bool) object {
	t.Helper()
	reasons, err := rp.ValidateManifest(m, dry, allocations)
	if err != nil {
		return errorObservation(err)
	}
	return normalize(t, object{"reasons": reasons})
}
func reasonsText(o object) string { return fmt.Sprint(o["reasons"]) }

func assertRuntimeError(t *testing.T, got object, errorType, reason string) {
	t.Helper()
	if got["error_type"] != errorType {
		t.Fatalf("want %s containing %q, got %#v", errorType, reason, got)
	}
	assertContains(t, fmt.Sprint(got["error"]), reason)
}
func assertPressureError(t *testing.T, got object, reason string) {
	t.Helper()
	assertRuntimeError(t, got, "HarnessError", reason)
