func pretty(v any) []byte {
	b, e := json.Marshal(v, json.Deterministic(true), jsontext.WithIndent("  "))
	if e != nil {
		fail("cannot encode evidence: %v", e)
	}
	return append(b, '\n')
}
func (r *Runner) ValidateQualifier(evidence, request Object, observed, phase string) (err error) {
	defer recoverError(&err)
	r.validateQualifier(evidence, request, observed, phase)
	return
}
func (r *Runner) validateQualifier(evidence, request Object, observed, phase string) {
	summary, probe := sub(evidence, "summary"), sub(evidence, "probe_evidence")
	if str(summary, "status") != "PASS" || probe["fresh_for_request_id"] != request["request_id"] {
		fail("qualify adapter must return fresh packaged probe PASS")
	}
	if Hash(pretty(summary)) != str(probe, "summary_sha256") || Hash([]byte(str(probe, "commands_log"))) != str(probe, "commands_sha256") {
		fail("qualify summary/commands log differs from exact content hashes")
	}
	role := str(request, "guest_role")
	if str(summary, "guest_role") != role {
		fail("qualifier guest role differs from pinned request")
	}
	identity, q, unit := sub(r.Manifest, "identity"), r.qualification(), HostUnit
	if role == "controller" {
		identity, q, unit = sub(r.Manifest, "controller_identity"), sub(r.Manifest, "controller_qualification"), ControllerUnit
	}
	units := sub(summary, "unit_sha256")
	if summary["qualifier_sha256"] != sub(sub(r.Manifest, "transport"), "runtime")["qualify_sha256"] || !exact(units, unit) || !hashRE.MatchString(str(units, unit)) {
		fail("qualify summary probe digest differs from CI pin or omits role unit hash")
	}
	fingerprint := Object{"qualifier_sha256": summary["qualifier_sha256"], "unit_sha256": units, "systemd_version": summary["systemd_version"]}
	fingerprints := r.stateObject("probe_fingerprint")
	if old := fingerprints[role]; old != nil && !same(old, fingerprint) {
		fail("%s qualifier or systemd unit identity changed during D15", role)
	}
	for _, k := range []string{"oci_instance_id", "image_id", "artifact_id", "config_id", "profile_id"} {
		if summary[k] != identity[k] {
			fail("%s qualify summary %s differs from pinned target", role, k)
		}
	}
	profile := sub(summary, "memory_profile")
	prefix := "expected_memory_"
	if role == "controller" {
		prefix = "expected_controller_memory_"
	}
	expected := Object{role + "_memory_min_bytes": q[prefix+"min_bytes"], role + "_memory_low_bytes": q[prefix+"low_bytes"], "system_slice_memory_min_bytes": q["expected_system_slice_memory_min_bytes"], "system_slice_memory_low_bytes": q["expected_system_slice_memory_low_bytes"], "system_reserve_bytes": q["system_reserve_bytes"], "allocatable_memory_bytes": q["allocatable_memory_bytes"]}
	for k, w := range expected {
		if !same(profile[k], w) {
			fail("%s qualify summary %s differs from pinned profile values", role, k)
		}
	}
	services := r.stateObject("service_snapshot")
	service := obj(services[unit], role+" qualification current service witness")
	processes, cgroups := sub(summary, "processes"), sub(summary, "cgroups")
	processKey := "host_supervisor"
	if role == "controller" {
		processKey = "controller"
	}
	process := sub(processes, processKey)
	if !same(process["pid"], service["main_pid"]) || process["process_start_time"] != service["process_start"] {
		fail("%s qualifier process differs from witnessed unit process", role)
	}
	servicePath := text(cgroups[role+"_service"], role+" service cgroup")
	if servicePath != filepath.Join(CgroupRoot, str(service, "control_group")) {
		fail("%s qualifier cgroup differs from witnessed unit", role)
	}
	if role == "host" {
		current := sub(sub(sub(r.snapshot(), "members"), "source"), "managed_identity")
		database := sub(processes, "terrabase")
		if !same(database["pid"], current["pid"]) || database["cgroup"] != current["cgroup"] {
			fail("priority probe TerraBase identity differs from accepted host report")
		}
		native, db, dbRole := qualifiedRoleCgroups(str(cgroups, "native_runner"), str(database, "cgroup"))
		roles := sub(cgroups, "roles")
		if str(sub(sub(roles, dbRole), "memory"), "memory_max") != strconv.FormatInt(n(r.qualification(), "database_memory_max_bytes"), 10) {
			fail("TerraBase cgroup memory.max differs from signed profile cap")
		}
		if r.State["native_runner_path"] != nil && (r.State["native_runner_path"] != native || r.State["database_cgroup_path"] != db) {
			fail("native runner or TerraBase cgroup path changed during qualification")
		}
		r.State["native_runner_path"], r.State["database_cgroup_path"] = native, db
	} else {
		if !exact(processes, "controller") || !exact(cgroups, "controller_service", "controller_weights", "controller_cpu_max") || !strings.HasPrefix(str(cgroups, "controller_cpu_max"), "max ") {
			fail("controller qualifier must contain only controller role state")
		}
	}
	sent, start, finish, obs := timestamp(request["sent_at_utc"], "qualify sent"), timestamp(summary["started_at_utc"], "qualify start"), timestamp(summary["finished_at_utc"], "qualify finish"), timestamp(observed, "qualify observed")
	if sent.After(start) || start.After(finish) || finish.After(obs) {
		fail("priority probe stale or outside exact request window")
	}
	sample, e := ValidateMemorySample(sub(summary, "memory_usage_sample"), MemoryValidation{Identity: identity, GuestRole: role, ServiceCgroup: servicePath, BootID: str(service, "host_boot_id"), SystemdVersion: str(summary, "systemd_version"), NotBefore: sent, NotAfter: finish})
	if e != nil {
		panic(e)
	}
	fingerprints[role] = fingerprint
	r.appendState("memory_usage_samples", Object{"phase": phase, "guest_role": role, "request_id": request["request_id"], "sample_sha256": sample["sample_sha256"]})
}

// Qualifier dependencies default to the live guest. Tests supply isolated roots
// and a command executor, without replacing any qualification decision.
type Qualifier struct {
	Args                                                    Object
	BakedProfile                                            func() (Object, error)
	CgroupRoot, ProcRoot, ProfilePath, UnitRoot, Executable string
	Command                                                 func(context.Context, []string) (string, error)
	AfterDirectoryOpen                                      func(string)
	ChildVisited                                            func(string)
	Log                                                     []string
}

func (p *Qualifier) roots() {
	if p.CgroupRoot == "" {
		p.CgroupRoot = CgroupRoot
	}
	if p.ProcRoot == "" {
		p.ProcRoot = "/proc"
	}
	if p.ProfilePath == "" {
		p.ProfilePath = "/etc/terrascale-orchestrator/runtime-priority.json"
	}
	if p.UnitRoot == "" {
		p.UnitRoot = "/etc/systemd/system"
	}
	if p.Executable == "" {
		p.Executable, _ = os.Executable()
	}
}

func (p *Qualifier) CaptureMemorySample(cgroups map[string]string, version string) (sample Object, err error) {
	defer recoverError(&err)
	p.roots()
	started := utcNow()
	rows := Object{}
	rootFD, e := unix.Open(p.CgroupRoot, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if e != nil {
		qfail("cannot anchor cgroup memory sample: %v", e)
	}
	defer unix.Close(rootFD)
	openDirectory := func(path string) (*os.File, error) {
		if !inside(path, p.CgroupRoot) {
			qfail("memory sample escaped cgroup root")
		}
		relative, e := filepath.Rel(p.CgroupRoot, path)
		if e != nil {
			return nil, e
		}
		fd, e := unix.Openat2(rootFD, relative, &unix.OpenHow{Flags: unix.O_RDONLY | unix.O_DIRECTORY | unix.O_CLOEXEC, Resolve: unix.RESOLVE_BENEATH | unix.RESOLVE_NO_SYMLINKS | unix.RESOLVE_NO_MAGICLINKS})
		if e != nil {
			return nil, e
		}
		return os.NewFile(uintptr(fd), path), nil
	}
	sameDirectory := func(path string, meta os.FileInfo) bool {
		named, e := openDirectory(path)
		if e != nil {
			return false
		}
		defer named.Close()
		current, e := named.Stat()
		return e == nil && os.SameFile(meta, current)
	}
	var systemDir *os.File
	var systemMeta os.FileInfo
	for _, scope := range slices.Sorted(maps.Keys(cgroups)) {
		path := cgroups[scope]
		if !inside(path, p.CgroupRoot) {
			qfail("%s memory sample escaped cgroup root", scope)
		}
		dir, e := openDirectory(path)
		if e != nil {
			qfail("cannot capture %s cgroup memory: %v", scope, e)
		}
		defer dir.Close()
		fd := int(dir.Fd())
		func() {
			meta, e := dir.Stat()
			if e != nil {
				qfail("cannot inspect cgroup directory: %v", e)
			}
			if p.AfterDirectoryOpen != nil {
				p.AfterDirectoryOpen(path)
			}
			check := func(stage string) {
				if !sameDirectory(path, meta) {
					qfail("%s memory sample cgroup changed %s capture", scope, stage)
				}
			}
			check("before")
			read := func(name string, max int64) string {
				f, e := unix.Openat(fd, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
				if e != nil {
					qfail("cannot read cgroup %s: %v", name, e)
				}
				file := os.NewFile(uintptr(f), name)
				defer file.Close()
				b, e := io.ReadAll(io.LimitReader(file, max+1))
				if e != nil {
					qfail("cannot read cgroup %s: %v", name, e)
				}
				if int64(len(b)) > max {
					qfail("%s %s exceeds its fixed evidence bound", scope, name)
				}
				return string(b)
			}
			current, peak, stat := read("memory.current", 128), read("memory.peak", 128), read("memory.stat", 16384)
			check("during")
			rows[scope] = Object{"cgroup_path": path, "cgroup_inode": meta.Sys().(*syscall.Stat_t).Ino, "memory_current_raw": current, "memory_current_bytes": integerText(current, "memory.current"), "memory_peak_raw": peak, "memory_peak_bytes": integerText(peak, "memory.peak"), "memory_stat_raw": stat, "memory_stat_sha256": Hash([]byte(stat))}
			if scope == "system_slice" {
				systemDir, systemMeta = dir, meta
			}
		}()
	}
	system := cgroups["system_slice"]
	if systemDir == nil || !sameDirectory(system, systemMeta) {
		qfail("system.slice memory sample cgroup changed before child enumeration")
	}
	children := []string{}
	size := 0
	for {
		entries, e := systemDir.ReadDir(1)
		if e == io.EOF {
			break
		}
		if e != nil {
			qfail("cannot enumerate system.slice: %v", e)
		}
		entry := entries[0]
		if p.ChildVisited != nil {
			p.ChildVisited(entry.Name())
		}
		if entry.Type()&os.ModeSymlink != 0 {
			qfail("system.slice contains symlink while child scopes sampled")
		}
		if !entry.IsDir() {
			continue
		}
		size += len(entry.Name())
		if len(children) >= 256 || size > 16384 {
			qfail("system.slice child-cgroup list exceeds its fixed evidence bound")
		}
		children = append(children, entry.Name())
	}
	if !sameDirectory(system, systemMeta) {
		qfail("system.slice memory sample cgroup changed during child enumeration")
	}
	slices.Sort(children)
	var u unix.Utsname
	if e := unix.Uname(&u); e != nil {
		qfail("cannot read kernel release: %v", e)
	}
	release := string(u.Release[:])
	release, _, _ = strings.Cut(release, "\x00")
	sample = Object{"schema": MemorySampleSchema, "guest_role": str(p.Args, "role"), "host_boot_id": strings.TrimSpace(readText(filepath.Join(p.ProcRoot, "sys/kernel/random/boot_id"), 128)), "kernel_release": release, "systemd_version": version, "started_at_utc": started, "finished_at_utc": utcNow(), "scopes": rows, "system_slice_direct_child_cgroups": children}
	for _, k := range []string{"oci_instance_id", "image_id", "artifact_id", "config_id", "profile_id"} {
		sample[k] = p.Args[k]
	}
	sample["sample_sha256"] = Hash(Canonical(sample))
	return
}

func ValidateMemorySample(sample Object, v MemoryValidation) (result Object, err error) {
	defer recoverError(&err)
	if v.CgroupRoot == "" {
		v.CgroupRoot = CgroupRoot
	}
	if !exact(sample, "schema", "guest_role", "oci_instance_id", "image_id", "artifact_id", "config_id", "profile_id", "host_boot_id", "kernel_release", "systemd_version", "started_at_utc", "finished_at_utc", "scopes", "system_slice_direct_child_cgroups", "sample_sha256") {
		fail("memory usage sample fields differ from pinned schema")
	}
	if str(sample, "schema") != MemorySampleSchema {
		fail("memory usage sample schema unsupported")
	}
	if (v.GuestRole != "host" && v.GuestRole != "controller") || str(sample, "guest_role") != v.GuestRole {
		fail("memory usage sample guest role differs from pinned target")
	}
	for _, k := range []string{"oci_instance_id", "image_id", "artifact_id", "config_id", "profile_id"} {
		if sample[k] != v.Identity[k] {
			fail("memory usage sample %s differs from the pinned target", k)
		}
	}
	if !uuidRE.MatchString(str(sample, "host_boot_id")) || str(sample, "host_boot_id") != v.BootID {
		fail("memory usage sample boot ID differs from accepted guest")
	}
	text(sample["kernel_release"], "memory usage sample kernel_release")
	if str(sample, "systemd_version") != v.SystemdVersion {
		fail("memory usage sample systemd version differs from packaged qualifier")
	}
	started, finished := timestamp(sample["started_at_utc"], "memory sample start"), timestamp(sample["finished_at_utc"], "memory sample finish")
	if v.NotBefore.After(started) || started.After(finished) || finished.After(v.NotAfter) {
		fail("memory usage sample is stale or outside its exact qualification request")
	}
	scopes := sub(sample, "scopes")
	serviceScope := v.GuestRole + "_service"
	if !exact(scopes, serviceScope, "system_slice") {
		fail("memory usage sample must contain selected service and system.slice scopes")
	}
	if !filepath.IsAbs(v.ServiceCgroup) || filepath.Base(filepath.Dir(v.ServiceCgroup)) != "system.slice" {
		fail("qualified service cgroup outside expected system.slice")
	}
	for scope, path := range map[string]string{serviceScope: v.ServiceCgroup, "system_slice": filepath.Dir(v.ServiceCgroup)} {
		row := sub(scopes, scope)
		if !exact(row, "cgroup_path", "cgroup_inode", "memory_current_raw", "memory_current_bytes", "memory_peak_raw", "memory_peak_bytes", "memory_stat_raw", "memory_stat_sha256") {
			fail("memory usage sample %s fields differ from pinned schema", scope)
		}
		if str(row, "cgroup_path") != path || !safePath(path) || !inside(path, v.CgroupRoot) {
			fail("memory usage sample %s cgroup differs from the exact unit scope", scope)
		}
		num(row["cgroup_inode"], "memory sample cgroup inode", 1)
		for _, kind := range []string{"current", "peak"} {
			raw := text(row["memory_"+kind+"_raw"], "memory sample counter")
			if len(raw) > 128 {
				fail("memory usage sample %s counter exceeds its fixed evidence bound", scope)
			}
			value := strings.TrimSuffix(raw, "\n")
			if !decimalRE.MatchString(value) {
				fail("memory usage sample counter must be decimal bytes")
			}
			if integerText(value, "memory sample counter") != num(row["memory_"+kind+"_bytes"], "memory sample counter bytes", 0) {
				fail("memory usage sample counter differs from raw cgroup value")
			}
		}
		if n(row, "memory_peak_bytes") < n(row, "memory_current_bytes") {
			fail("memory usage sample peak below current usage")
		}
		raw := text(row["memory_stat_raw"], "memory sample stat")
		if len(raw) > 16384 {
			fail("memory usage sample %s memory.stat exceeds its fixed evidence bound", scope)
		}
		statValues(raw)
		if !hashRE.MatchString(str(row, "memory_stat_sha256")) || Hash([]byte(raw)) != str(row, "memory_stat_sha256") {
			fail("memory usage sample memory.stat hash differs from raw value")
		}
	}
	children := stringsList(sample["system_slice_direct_child_cgroups"], "memory sample child scopes")
	if len(children) > 256 {
		fail("memory usage sample system.slice child list exceeds its fixed evidence bound")
	}
	size := 0
	for _, name := range children {
		if name == "" {
			fail("memory usage sample child list malformed")
		}
		size += len(name)
	}
	if size > 16384 {
		fail("memory usage sample child list exceeds its fixed evidence bound")
	}
	if !slices.IsSorted(children) || len(slices.Compact(slices.Clone(children))) != len(children) {
		fail("memory usage sample child list malformed or unordered")
	}
	if !slices.Contains(children, filepath.Base(v.ServiceCgroup)) {
		fail("memory usage sample system.slice does not list protected service cgroup")
	}
	unhashed := clone(sample)
	delete(unhashed, "sample_sha256")
	if !hashRE.MatchString(str(sample, "sample_sha256")) || Hash(Canonical(unhashed)) != str(sample, "sample_sha256") {
		fail("memory usage sample hash differs from its canonical contents")
	}
	return sample, nil
}

func shiftObservation(t *testing.T, value any, delta time.Duration) any {
	t.Helper()
	switch v := value.(type) {
	case string:
		if stamp, err := time.Parse(time.RFC3339Nano, v); err == nil {
			return sampleTimestamp(stamp.Add(delta))
		}
		if strings.HasPrefix(v, "{") || strings.HasPrefix(v, "[") {
			var data any
			if json.Unmarshal([]byte(v), &data) == nil {
				data = shiftObservation(t, data, delta)
				raw, err := json.Marshal(data, json.Deterministic(true))
				if err != nil {
					t.Fatal(err)
				}
				return string(raw)
			}
		}
		return v
	case []any:
		for i, item := range v {
			v[i] = shiftObservation(t, item, delta)
		}
		return v
	case map[string]any:
		for key, item := range v {
			if key == "__REALTIME_TIMESTAMP" {
				if s, ok := item.(string); ok {
					n, err := strconv.ParseInt(s, 10, 64)
					if err != nil {
						t.Fatal(err)
					}
					v[key] = strconv.FormatInt(n+delta.Microseconds(), 10)
					continue
				}
			}
			v[key] = shiftObservation(t, item, delta)
		}
		for rawKey, hashKey := range map[string]string{"operator_hosts_json": "operator_hosts_sha256", "worker_state_record": "worker_state_sha256", "journal_watermark_raw_record": "journal_watermark_raw_record_sha256", "raw_record": "raw_record_sha256", "transaction_request_raw": "transaction_request_sha256", "write_receipt_raw": "write_receipt_sha256", "peer_read_raw": "peer_read_sha256"} {
			if raw, ok := v[rawKey].(string); ok {
				v[hashKey] = digest([]byte(raw))
			}
		}
		return v
	default:
		return value
	}
}
func pressureInputs(t *testing.T, name string) []any {
	t.Helper()
	fixtures := decodeObject(t, script.Read(t, filepath.Join(script.Root(t), "tests/runtime_priority/testdata/pressure-observations.json")))
	records := fixtures[name].([]any)
	// The clock is shifted by Go so process-report age and journal windows remain
	// realistic while preserving the intervals that each case exercises.
	origin := fixtures["test_oom_event_and_receipt_bind_exact_role_and_restored_signed_cap"].([]any)[0].(map[string]any)["args"].([]any)[2].(string)
	stamp, err := time.Parse(time.RFC3339Nano, origin)
	if err != nil {
		t.Fatal(err)
	}
	delta := time.Since(stamp)
	return shiftObservation(t, records, delta).([]any)
}
func mergeObservation(target, patch object) {
	for key, value := range patch {
		if nested, ok := value.(map[string]any); ok {
			if current, ok := target[key].(map[string]any); ok {
				mergeObservation(current, nested)
				continue
			}
		}
		target[key] = value
	}
}

func replayPressureInput(t *testing.T, record object, inspect ...string) object {
	t.Helper()
	setupStarted := time.Now()
	record["inspect"] = inspect
	if state, ok := record["state"].(map[string]any); ok {
		manifest := exampleManifest(t)
		mergeObservation(manifest, field(state, "manifest_patch"))
		delete(state, "manifest_patch")
		state["manifest"] = manifest
		if _, ok := state["harness_sha256"]; ok {
			binary, err := os.Executable()
			if err != nil {
				t.Fatal(err)
			}
			hash := digest(script.Read(t, binary))
			state["harness_sha256"] = hash
			for _, arg := range record["args"].([]any) {
				if arg, ok := arg.(map[string]any); ok {
					if _, ok := arg["worker_harness_sha256"]; ok {
						arg["worker_harness_sha256"] = hash
					}
				}
			}
		}
		state["evidence_dir"] = object{"$path": t.TempDir()}
	}
	if record["operation"] == "_validate_pressure" {
		evidence := record["args"].([]any)[1].(map[string]any)
		observed := field(evidence, "pressure_cgroup")
		device := observed["io_device"].(string)
		observed["io_backing"] = normalize(t, object{"filesystem_device": device, "mountpoint": "/var/tmp", "filesystem_type": "xfs", "block_leaf_devices": []string{"8:0"}, "block_device_chain": []object{{"device": device, "sysfs_path": "/sys/devices/virtual/block/dm-0", "subsystem": "block", "virtual": true, "pseudo": false, "partition_parent": nil, "slaves": []string{"8:0"}, "size_sectors": 100000}, {"device": "8:0", "sysfs_path": "/sys/devices/pci/block/sda", "subsystem": "block", "virtual": false, "pseudo": false, "partition_parent": nil, "slaves": []string{}, "size_sectors": 100000}}})
	}
	record = restoreRecord(record).(map[string]any)
	args := record["args"].([]any)
	operation := record["operation"].(string)
	var value any
	var err error
	var runner *rp.Runner
	if state, ok := record["state"].(map[string]any); ok {
		runner = rp.NewRunner(field(state, "manifest"), state["manifest_hash"].(string), state["evidence_dir"].(string))
		for key, v := range state {
			runner.State[key] = v
		}
	}
	switch operation {
	case "_qualified_role_cgroups":
		a, b, c, e := rp.QualifiedRoleCgroups(args[0].(string), args[1].(string))
		value = []any{a, b, c}
		err = e
	case "validate_report_evidence":
		value, err = rp.ValidateReportEvidence(args[0].(map[string]any), args[1].(map[string]any), args[2].(string), args[3].(map[string]any), args[4].(map[string]any))
	case "validate_database_wire":
		value, err = rp.ValidateDatabaseWire(args[0].(map[string]any), args[1].(map[string]any), args[2].(map[string]any))
	case "_compare_services":
		err = runner.CompareServices(args[0].(map[string]any), args[1].(string))
	case "_failure_target":
		// Native executable hashing can exceed the witness window under the
		// race detector. Preserve the fixture's report age at validator entry.
		runner.State = shiftObservation(t, runner.State, time.Since(setupStarted)).(map[string]any)
		value, err = runner.FailureTarget()
	case "_validate_role":
		err = runner.ValidateRole(args[0].(string), args[1].(string), args[2].(map[string]any), args[3].(map[string]any))
	case "_validate_pressure":
		err = runner.ValidatePressure(args[0].(string), args[1].(map[string]any), args[2].(map[string]any), args[3].(map[string]any))
	case "_validate_oom":
		err = runner.ValidateOOM(args[0].(map[string]any), args[1].(map[string]any), args[2].(string))
	default:
		t.Fatalf("unhandled native validation %s", operation)
	}
	result := errorObservation(err)
	if err == nil {
		result["value"] = value
	}
	if runner != nil {
		state := object{}
		for _, key := range inspect {
			state[key] = runner.State[key]
		}
		result["state"] = state
	}
	return normalize(t, result)
}

func restoreRecord(value any) any {
	switch v := value.(type) {
	case map[string]any:
		if len(v) == 1 {
			if path, ok := v["$path"].(string); ok {
				return path
			}
			if stamp, ok := v["$datetime"].(string); ok {
				return stamp
			}
		}
		out := object{}
		for key, item := range v {
			out[key] = restoreRecord(item)
		}
		return out
	case []any:
		out := make([]any, len(v))
		for i, item := range v {
			out[i] = restoreRecord(item)
		}
		return out
	default:
		return v
	}
}

